model:
rachana: 1
sutra: book-desk
version: 1
description: 
match: { kind: portfolio-trades, priority: 1 }
title: { pill: "Book desk", id: "$.PORTFOLIO", with: "link($.PORTFOLIO, 'book')" }
strip:
  - { label: "Trades", bind: "$.TRADE_COUNT", emphasis: true }
  - { label: "Notional (all currencies)", bind: "$.NOTIONAL", fmt: "compact" }
  - { label: "Product types", bind: "size($.PRODUCT_TYPES)" }
  - { label: "Last maturity", bind: "$.LAST_MATURITY", fmt: "date" }
panels:
  - id: trades
    kind: table
    title: "Trades of the book"
    code: "TRD"
    phone: { tier: "glance", from: "fragment" }
    form: { title: "Edit trade", key: "trade_id", edit: "beside", new: "drawer", new-label: "New trade", save: { kind: "trade", target: "overlay", approval: "one", reason: "required" }, steps: [{ id: "who", label: "Who" }, { id: "what", label: "What" }, { id: "check", label: "Check" }], fields: [{ id: "trade_id", label: "Trade", bind: "TRADE_ID", readonly: true, reason: "set by the booking system", new: false }, { id: "counterparty", label: "Counterparty", bind: "COUNTERPARTY", type: "lookup", required: true, readonly: true, step: "who", options: { source: { pack: "counterparty-risk", kind: "credit-limit", where: "nonblank(@.COUNTERPARTY)" }, value: "COUNTERPARTY", label: "COUNTERPARTY_NAME", carry: ["LIMIT", "USED"] } }, { id: "product_type", label: "Product", bind: "PRODUCT_TYPE", type: "enum", options: ["IRS", "OIS", "XCCY", "FRA", "ComSwap", "Swaption"], readonly: true, reason: "the product is fixed once booked", required: true, step: "what" }, { id: "legal_entity", label: "Booked in", bind: "LEGAL_ENTITY", type: "entity", readonly: true, reason: "the booking entity is fixed once booked", step: "who", options: { source: { pack: "core", kind: "legal-entity" }, label: "NAME" } }, { id: "notional", label: "Notional", bind: "NOTIONAL", type: "money", currency: "currency", min: 0, required: true, fmt: "amount0", step: "what" }, { id: "currency", label: "Currency", bind: "CURRENCY", type: "enum", options: ["USD", "EUR", "GBP", "JPY", "CHF", "CAD", "AUD"], step: "what" }, { id: "upfront_fee", label: "Upfront fee", bind: "UPFRONT_FEE", type: "money", currency: "currency", min: 0, default: "=notional * 0.001", fmt: "amount0", step: "what" }, { id: "executed_at", label: "Executed", bind: "EXECUTED_AT", type: "datetime", tz: "Europe/London", step: "what" }, { id: "maturity_date", label: "Maturity", bind: "MATURITY_DATE", type: "date", min: "today", required: true, step: "what" }, { id: "trade_status", label: "Status", bind: "TRADE_STATUS", type: "enum", options: ["PENDING", "VALIDATED", "AMENDED"], editable-by: ["middle-office"], new: false }, { id: "comment", label: "Comment", bind: "COMMENT", type: "textarea", max-length: 500, placeholder: "Reason for the change", step: "check" }], rules: [{ rule: "notional <= 30000000", severity: "warn", fields: ["notional"], message: "Above the desk limit of 30,000,000: a second approver is needed." }, { rule: "not (notional > 30000000 and empty(comment))", fields: ["comment"], message: "Say why the trade is above the desk limit: the second approver reads it." }], hints: [{ label: "PFE limit after this trade", value: "counterparty.USED + notional", of: "counterparty.LIMIT", fmt: "amount0", step: "what" }] }
    rows: "$.TRADES"
    empty: "No trades in this book"
    columns:
      - { label: "Trade", bind: "@.TRADE_ID" }
      - { label: "Product", bind: "@.PRODUCT_TYPE" }
      - { label: "Counterparty", bind: "@.COUNTERPARTY" }
      - { label: "Notional", bind: "@.NOTIONAL", fmt: "amount0", total: true }
      - { label: "Maturity", bind: "@.MATURITY_DATE", fmt: "date" }
  - id: counterparty
    kind: kv
    title: "Counterparty"
    area: right
    columns:
      - { label: "Name", bind: "$src.NAME" }
      - { label: "Rating", bind: "$src.RATING" }
      - { label: "Sector", bind: "$src.SECTOR" }
      - { label: "Country", bind: "$src.COUNTRY" }
  - id: limit
    kind: kv
    title: "Credit limit"
    area: right
    columns:
      - { label: "Measure", bind: "$src[0].MEASURE" }
      - { label: "Limit", bind: "$src[0].LIMIT", fmt: "compact" }
      - { label: "Used", bind: "$src[0].USED", fmt: "compact" }
      - { label: "Utilisation", bind: "$src[0].UTILISATION", fmt: "pct0" }
      - { label: "Status", bind: "$src[0].STATUS", tone: "status" }
  - id: buckets
    kind: hbar
    title: "Utilisation by tenor"
    area: right
    phone: { tier: "glance", from: "fragment", rows: 5 }
    rows: "$src[0].BUCKETS"
    label: "BUCKET"
    value: "UTILISATION"
    fmt: "pct0"
  - id: built
    kind: provenance
    title: "How this view was built"
    phone: { tier: "more", from: "fragment" }
